#include <openssl/md5.h>
#include <string>
#include <vector>
#include <iostream>

inline const unsigned long kModulo = 65535;
inline const unsigned long kBase = 13;

float consistent_hash(const std::string &msg) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((const unsigned char*)msg.c_str(), msg.length(), digest);

    unsigned long sum = 0;
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sum += (unsigned long)digest[i] * (unsigned long)std::pow(kBase, i);
    }

    return (float)(sum % kModulo) / (float)kModulo;
}

int main() {
    std::cout << consistent_hash("test") << std::endl;
    return 0;
}

#include <openssl/md5.h>
#include <string>
#include <iostream>
#include <cmath>

inline const unsigned long kModulo = 65535;
inline const unsigned long kBase = 13;

float consistent_hash(const std::string &msg) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5(reinterpret_cast<const unsigned char*>(msg.c_str()), msg.length(), digest);

    unsigned long sum = 0;
    unsigned long current_base_pow = 1;
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sum += (unsigned long)digest[i] * current_base_pow;
        current_base_pow *= kBase;
    }

    return static_cast<float>(sum % kModulo) / static_cast<float>(kModulo);
}

int main() {
    std::cout << consistent_hash("test") << std::endl;
    return 0;
}

